// TestRouteStatus_lastDecisionCached verifies that calling ResolveRoute and
// then RouteStatus surfaces the cached LastDecision on the matching entry.
func TestRouteStatus_lastDecisionCached(t *testing.T) {
	// Build a minimal ServiceConfig that satisfies the routing engine.
	sc := &fakeServiceConfig{
		providers: map[string]ServiceProviderEntry{
			"bragi": {Type: "lmstudio", BaseURL: "http://127.0.0.1:9999/v1", Model: "qwen3-27b"},
		},
		names:       []string{"bragi"},
		defaultName: "bragi",
	}

	// Seed registry with the "fiz" harness available so routing can resolve.
	reg := harnesses.NewRegistry()
	svc := &service{
		opts:     ServiceOptions{ServiceConfig: sc},
		registry: reg,
	}

	// Inject a decision directly into the cache (simulating a resolved route)
	// since ResolveRoute may fail without a real provider.
	dec := &RouteDecision{
		Harness:        "fiz",
		Provider:       "bragi",
		Endpoint:       "desk-a",
		ServerInstance: "desk-a",
		Model:          "qwen3-27b",
		Reason:         "test",
		Sticky:         RouteStickyState{KeyPresent: true, Assignment: "reused", ServerInstance: "desk-a", Reason: "live sticky lease reused"},
	}
	svc.cacheRouteDecision("qwen3-27b", dec)

	report, err := svc.RouteStatus(context.Background())
	if err != nil {
		t.Fatalf("RouteStatus: %v", err)
	}
	if len(report.Routes) != 1 {
		t.Fatalf("Routes: got %d, want 1", len(report.Routes))
	}
	entry := report.Routes[0]
	if entry.LastDecision == nil {
		t.Fatal("LastDecision: expected non-nil after ResolveRoute")
	}
	if entry.LastDecision.Provider != "bragi" {
		t.Errorf("LastDecision.Provider: got %q, want %q", entry.LastDecision.Provider, "bragi")
	}
	if entry.LastDecision.ServerInstance == "" {
		t.Errorf("LastDecision.ServerInstance should be populated: %#v", entry.LastDecision)
	}
	if entry.LastDecision.Model != "qwen3-27b" {
		t.Errorf("LastDecision.Model: got %q, want %q", entry.LastDecision.Model, "qwen3-27b")
	}
	if entry.LastDecisionAt.IsZero() {
		t.Error("LastDecisionAt: should be non-zero")
	}
	if entry.SelectedEndpoint != "desk-a" {
		t.Fatalf("SelectedEndpoint = %q, want desk-a", entry.SelectedEndpoint)
	}
	if entry.SelectedServerInstance == "" {
		t.Fatalf("SelectedServerInstance should be populated: %#v", entry)
	}
	if !entry.Sticky.KeyPresent || entry.Sticky.Assignment != "reused" {
		t.Fatalf("Sticky = %#v, want reused sticky evidence", entry.Sticky)
	}
}

// TestRouteStatus_lastDecisionCached_viaResolveRoute verifies the full path:
// ResolveRoute → cache write → RouteStatus reads cache.
func TestRouteStatus_lastDecisionCached_viaResolveRoute(t *testing.T) {
	// We need the routing engine to actually resolve. The engine picks
	// harnesses from the registry. "fiz" is always in the registry.
	// We give it a provider so the engine can build a candidate.
	sc := &fakeServiceConfig{
		providers: map[string]ServiceProviderEntry{
			"bragi": {Type: "lmstudio", BaseURL: "http://127.0.0.1:9999/v1", ServerInstance: "bragi-instance", Model: "mymodel"},
		},
		names:       []string{"bragi"},
		defaultName: "bragi",
	}

	svc := &service{
		opts:     ServiceOptions{ServiceConfig: sc},
		registry: harnesses.NewRegistry(),
	}

	// ResolveRoute with model="mymodel". The engine resolves against the
	// "fiz" harness + bragi provider.
	dec, err := svc.ResolveRoute(context.Background(), RouteRequest{
		Model:    "mymodel",
		Provider: "bragi",
	})
	if err != nil {
		// Routing may return an error if the engine can't fully resolve;
		// skip in that case — the direct-cache test covers the cache logic.
		t.Skipf("ResolveRoute returned error (provider not live): %v", err)
	}
	if dec == nil {
		t.Fatal("RouteDecision: nil")
	}

	report, err := svc.RouteStatus(context.Background())
	if err != nil {
		t.Fatalf("RouteStatus: %v", err)
	}
	var found *RouteStatusEntry
	for i := range report.Routes {
		if report.Routes[i].Model == "mymodel" {
			found = &report.Routes[i]
			break
		}
	}
	if found == nil {
		t.Fatal("route 'mymodel' not found in report")
	}
	if found.LastDecision == nil {
		t.Fatal("LastDecision: expected non-nil after successful ResolveRoute")
	}
	if dec.Endpoint != "" && found.SelectedEndpoint != dec.Endpoint {
		t.Fatalf("SelectedEndpoint = %q, want %q", found.SelectedEndpoint, dec.Endpoint)
	}
}

func TestRouteStatus_attemptCooldownStateSurfaces(t *testing.T) {
	sc := &fakeServiceConfig{
		healthCooldown: 30 * time.Second,
		providers: map[string]ServiceProviderEntry{
			"bragi":      {Type: "lmstudio", BaseURL: "http://bragi.invalid/v1", Model: "qwen3-27b"},
			"openrouter": {Type: "openrouter", BaseURL: "https://openrouter.invalid/v1", Model: "qwen3-27b"},
		},
		names: []string{"bragi", "openrouter"},
	}
	svc := newTestService(t, ServiceOptions{ServiceConfig: sc})
	recordedAt := time.Now().Add(-time.Second).UTC()
	if err := svc.RecordRouteAttempt(context.Background(), RouteAttempt{
		Harness:   "fiz",
		Provider:  "bragi",
		Model:     "qwen3-27b",
		Status:    "failed",
		Reason:    "rate_limit",
		Timestamp: recordedAt,
	}); err != nil {
		t.Fatalf("RecordRouteAttempt: %v", err)
	}

	report, err := svc.RouteStatus(context.Background())
	if err != nil {
		t.Fatalf("RouteStatus: %v", err)
	}
	if len(report.Routes) != 1 {
		t.Fatalf("Routes: got %d, want 1", len(report.Routes))
	}

	entry := report.Routes[0]
	if len(entry.Candidates) != 2 {
		t.Fatalf("Candidates: got %d, want 2", len(entry.Candidates))
	}

	// Find bragi and openrouter candidates.
	byProvider := make(map[string]RouteCandidateStatus, 2)
	for _, c := range entry.Candidates {

		SuccessRate float64 `json:"success_rate"`
		Capability  float64 `json:"capability"`
	}
	type sticky struct {
		KeyPresent bool   `json:"key_present"`
		Assignment string `json:"assignment"`
		Reason     string `json:"reason"`
	}
	type utilization struct {
		Source         string   `json:"source"`
		Freshness      string   `json:"freshness"`
		ActiveRequests *int     `json:"active_requests"`
		QueuedRequests *int     `json:"queued_requests"`
		MaxConcurrency *int     `json:"max_concurrency"`
		CachePressure  *float64 `json:"cache_pressure"`
	}
	type candidate struct {
		Harness      string      `json:"harness"`
		Provider     string      `json:"provider"`
		Endpoint     string      `json:"endpoint"`
		Model        string      `json:"model"`
		Score        float64     `json:"score"`
		Components   component   `json:"components"`
		Utilization  utilization `json:"utilization"`
		Eligible     bool        `json:"eligible"`
		FilterReason string      `json:"filter_reason"`
		Winner       bool        `json:"winner"`
	}
	var parsed struct {
		Model            string      `json:"model"`
		SelectedEndpoint string      `json:"selected_endpoint"`
		Sticky           sticky      `json:"sticky"`
		Utilization      utilization `json:"utilization"`
		Winner           *candidate  `json:"winner"`
		Candidates       []candidate `json:"candidates"`
	}
	require.NoError(t, json.Unmarshal([]byte(out.stdout), &parsed), "stdout=%s", out.stdout)
	assert.Equal(t, "qwen3.5-27b", parsed.Model)
	var generic map[string]json.RawMessage
	require.NoError(t, json.Unmarshal([]byte(out.stdout), &generic), "stdout=%s", out.stdout)
	for _, key := range []string{"selected_endpoint", "sticky", "utilization"} {
		if _, ok := generic[key]; !ok {
			t.Fatalf("missing %q in route-status JSON: %s", key, out.stdout)
		}
	}
	var candidateGeneric []map[string]json.RawMessage
	require.NoError(t, json.Unmarshal(generic["candidates"], &candidateGeneric))
	if len(candidateGeneric) == 0 {
		t.Fatal("expected at least one candidate in route-status JSON")
	}
	if _, ok := candidateGeneric[0]["utilization"]; !ok {
		t.Fatalf("missing candidate utilization in route-status JSON: %s", out.stdout)
	}

	// Each candidate carries the new structured shape from
	// service.ResolveRoute: provider, model, score, components, eligible bool,
	// and filter_reason (empty for the eligible winner, non-empty for losers).
	require.NotEmpty(t, parsed.Candidates)
	for _, c := range parsed.Candidates {
		// Subscription harnesses (claude/codex/gemini) surface harness-level
		// candidates with no Provider; native fiz harness candidates do
		// carry a Provider. Either way the routing identity (Harness or
		// Provider) must be populated.
		assert.True(t, c.Harness != "" || c.Provider != "", "candidate must carry a harness or provider: %+v", c)
		// Eligible candidates must name a resolved model. Ineligible
		// subscription-harness candidates (claude / codex / gemini that
		// fail health because their CLI isn't on PATH — common in CI)
		// legitimately surface with empty Model; the FilterReason
		// covers them.
		if c.Eligible {
			assert.NotEmpty(t, c.Model, "eligible candidate must carry a resolved model: %+v", c)
		}
		// Components is always present; its zero value is meaningful (unknown).
		_ = c.Components
		if !c.Eligible {
			assert.NotEmpty(t, c.FilterReason, "ineligible candidate must carry a filter_reason: %+v", c)
		}
	}

	// At least one candidate must be eligible (the two healthy lmstudio
	// providers serve qwen3.5-27b; bragi is dead and gets dropped before the
	// engine ever sees it because its /v1/models probe fails).
	eligibleCount := 0
	for _, c := range parsed.Candidates {
		if c.Eligible {
			eligibleCount++
		}
	}
	assert.GreaterOrEqual(t, eligibleCount, 1, "expected at least one eligible candidate; got %+v", parsed.Candidates)

	require.NotNil(t, parsed.Winner, "an eligible winner must be selected")
	assert.True(t, parsed.Winner.Eligible)
	assert.Empty(t, parsed.Winner.FilterReason, "winner must have an empty filter_reason")
	assert.Equal(t, parsed.Winner.Endpoint, parsed.SelectedEndpoint)
	assert.False(t, parsed.Sticky.KeyPresent, "no correlation id was supplied, so sticky key should be absent")

	// The winner must also appear inside the candidates array and be flagged.
	winnerInList := 0
	for _, c := range parsed.Candidates {
		if c.Winner {
			winnerInList++
			assert.Equal(t, parsed.Winner.Provider, c.Provider)
			assert.Equal(t, parsed.Winner.Model, c.Model)
		}
	}
	assert.Equal(t, 1, winnerInList, "exactly one candidate should be flagged winner")
	for _, c := range parsed.Candidates {
		_ = c.Utilization.Source
		_ = c.Utilization.Freshness
	}
}

// TestRouteStatus_ShowsEligibleCandidatesPerIntent asserts that
// `fiz route-status --profile <p>` calls service.ResolveRoute and
// renders the engine's full candidate trace for the requested policy
// profile, including the structured power-policy evidence and candidate
// score components. Per ADR-005 §5.
func TestRouteStatus_ShowsEligibleCandidatesPerIntent(t *testing.T) {
	exe := buildAgentCLI(t)
	workDir := t.TempDir()
	home := t.TempDir()

	// Discover a local power-5 model so the agent harness has at least one
	// eligible candidate under the balanced profile. Subscription harnesses
	// also surface candidates but go ineligible without quota state,
	// exercising both eligible and ineligible code paths.
	healthy := newCountedOpenAIServer(t, http.StatusOK, "qwen3.5-27b", "ok")
	healthy.setModels("qwen3.5-27b")

	writeTempConfig(t, workDir, `
providers:
  vidar:
    type: lmstudio
    base_url: `+healthy.baseURL()+`
    api_key: test
    model: qwen3.5-27b
`)

	out := runBuiltCLI(t, exe, workDir, testEnvWithHome(home, nil), "--work-dir", workDir, "route-status", "--profile", "standard", "--json")
	require.Equal(t, 0, out.exitCode, "stdout=%s stderr=%s", out.stdout, out.stderr)

	type component struct {
		Cost        float64 `json:"cost"`
		LatencyMS   float64 `json:"latency_ms"`
		SuccessRate float64 `json:"success_rate"`
		Capability  float64 `json:"capability"`
	}
	type candidate struct {
		Harness      string    `json:"harness"`
		Provider     string    `json:"provider"`
		Model        string    `json:"model"`
		Score        float64   `json:"score"`
		Components   component `json:"components"`
		Eligible     bool      `json:"eligible"`
		FilterReason string    `json:"filter_reason"`
		Reason       string    `json:"reason"`
		Winner       bool      `json:"winner"`
	}
	var parsed struct {
		Profile     string `json:"profile"`
		PowerPolicy struct {
			Profile  string `json:"profile"`
			MinPower int    `json:"min_power"`
			MaxPower int    `json:"max_power"`
		} `json:"power_policy"`
		Winner     *candidate  `json:"winner"`
		Candidates []candidate `json:"candidates"`
	}
	require.NoError(t, json.Unmarshal([]byte(out.stdout), &parsed), "stdout=%s", out.stdout)
	assert.Equal(t, "standard", parsed.Profile)
	assert.Equal(t, "standard", parsed.PowerPolicy.Profile)
	require.NotEmpty(t, parsed.Candidates, "engine must surface its candidate trace; stdout=%s", out.stdout)

	// Every candidate carries the score-component bundle (cost, latency_ms,
	// success_rate, capability) plus an eligible bool and a filter_reason
	// string that explains rankings without parsing free-form Reason text.
	sawIneligibleWithReason := false
	sawIneligible := false
	for _, c := range parsed.Candidates {
		// Eligible candidates must name a concrete model. Ineligible
		// subscription-harness candidates (claude / codex / gemini)
		// surface with Model:"" in environments without their CLI on
		// PATH (e.g., CI); FilterReason is the explanation there.
		if c.Eligible {
			assert.NotEmpty(t, c.Model, "eligible candidate must name a concrete model: %+v", c)
		}
		// Components is structured (not free-form); reading the four named
		// axes proves the wire shape matches AC §2.
		_ = c.Components.Cost
		_ = c.Components.LatencyMS
		_ = c.Components.SuccessRate
		_ = c.Components.Capability
		if !c.Eligible {
			sawIneligible = true
			if c.FilterReason != "" {
				sawIneligibleWithReason = true
			}
		}
	}
	if sawIneligible {
		assert.True(t, sawIneligibleWithReason,
			"at least one ineligible candidate must carry a non-empty filter_reason; got %+v",
			parsed.Candidates)
	}
}

