// Higher is better.
//
// Routing priority policy (ported from DDx routing.go):
//   - cheap: local + low-cost preferred; subscription-within-quota next.
//   - standard: balanced; light local/subscription preference to avoid spend.
//   - smart: quality first; cloud capability wins; no local bonus.
//
// The policy is profile-aware AND provider-aware via providerBias hooks
// supplied by the caller (cooldown demotion, observation perf bias,
// provider-affinity bias).
func scorePolicy(profile string, cand candidateInternal) float64 {
	base := 100.0
	cr := costClassRank[cand.CostClass]
	withinQuota := cand.IsSubscription && cand.QuotaOK

	switch profile {
	case "cheap":
		if cand.CostClass == "local" {
			base += 40
		} else if withinQuota {
			base += 20
		}
		base -= float64(cr) * 30

	case "standard":
		if cand.CostClass == "local" {
			base += 25
		} else if withinQuota {
			base += 15
		}
		base -= float64(cr) * 10

	case "smart":
		// Quality first; higher cost rank approximates higher capability.
		base += float64(cr) * 20
		if withinQuota {
			base += 5
		}

	default:
		// Treat unspecified as standard.
		if cand.CostClass == "local" {
			base += 25
		} else if withinQuota {
			base += 15
		}
		base -= float64(cr) * 10
	}

	// Provider preference bias.
	switch cand.ProviderPreference {
	case "local-first", "":
		if cand.CostClass == "local" {
			base += 30
		}
	case "subscription-first":
		if cand.IsSubscription && cand.QuotaOK {
			base += 30
		}
	}

	// Quota signals.
	if cand.IsSubscription {
		// Stale quota penalty.
		if cand.QuotaStale {
			base -= 15
		}

		// Trend-based adjustments.
		switch cand.QuotaTrend {
		case "exhausting":
			base -= 40
		case "burning":
			base -= 20
		case "healthy":
			base += 10
		}

		// Quota near-limit penalty (>= 80% used).
		if cand.QuotaPercentUsed >= 80 {
			base -= float64(cand.QuotaPercentUsed-80) * 2
		}
	}

	// Historical success-rate adjustment (only when sufficient samples).
	if cand.HistoricalSuccessRate >= 0 {
		switch {
		case cand.HistoricalSuccessRate >= 0.8:
			base += 20
		case cand.HistoricalSuccessRate < 0.5:
			base -= 30
		}
	}
	if cand.ProviderSuccessRate >= 0 {
		switch {
		case cand.ProviderSuccessRate >= 0.8:
			base += 25
		case cand.ProviderSuccessRate < 0.5:
			base -= 35
		}
	}

	// Cooldown demotion: candidate has had recent failures.
	if cand.InCooldown {
		base -= 50
	}

	// Provider affinity: explicit provider pins are filtered before scoring;
	// this bonus only affects the ordering among still-eligible candidates
	// that share the pinned provider identity.
	if cand.ProviderAffinityMatch {
		base += 15
	}

	if cand.Power > 0 {
		base += float64(cand.Power) * 12
	}
	if cand.Power > 0 && cand.CostUSDPer1kTokens > 0 {
		costPenalty := cand.CostUSDPer1kTokens * 500
		if costPenalty > 60 {
			costPenalty = 60
		}
		base -= costPenalty
	}
	if cand.Power > 0 && cand.CostUSDPer1kTokens == 0 {
		switch {
		case cand.CostClass == "local":
			base += 15
		case cand.IsSubscription && cand.QuotaOK && !cand.QuotaStale && cand.QuotaPercentUsed < 80:
			base += 15
		}
	}
	if cand.Power >= 9 && cand.IsSubscription && cand.QuotaOK && !cand.QuotaStale && cand.QuotaPercentUsed < 80 {
		base += 20
	}

	// Observation-derived perf bias.
	if cand.ObservedTokensPerSec > 0 {
		// Small additive bonus, scaled.
		base += cand.ObservedTokensPerSec / 100.0
	}
	if cand.ObservedLatencyMS > 0 {
		// Latency is a tiebreaker-scale signal: faster endpoints gain a small
		// bonus while very slow endpoints receive little benefit.
		base += 1000.0 / cand.ObservedLatencyMS
	}
	if cand.CostClass == "experimental" {
		base -= 75
	}

	return base
}

package compaction

import (
	"strings"

	agent "github.com/DocumentDrivenDX/fizeau/internal/core"
)

// DefaultContextWindow is used when no context window is configured.
// Most modern models support at least 128k; 8k caused premature compaction
// and stuck loops on models where LM Studio doesn't report context length.
const DefaultContextWindow = 131072

// DefaultReserveTokens is the token budget reserved for the model response.
const DefaultReserveTokens = 8192

// DefaultKeepRecentTokens is how many tokens of recent messages to keep verbatim.
const DefaultKeepRecentTokens = 8192

// DefaultMaxToolResultChars is the max chars per tool result in summarization input.
const DefaultMaxToolResultChars = 2000

// DefaultEffectivePercent is the safety margin on the context window.
const DefaultEffectivePercent = 95

// DefaultUserMessageTailTokens is the default token budget for re-including
// recent real user messages alongside the compaction summary.
const DefaultUserMessageTailTokens = 20000

// DefaultStuckThreshold is the number of consecutive compaction attempts that
// return without producing a compacted history before the compactor reports
// ErrCompactionStuck. Only attempts where ShouldCompact returns true count;
// normal no-ops (below threshold, already summarised) do not.
const DefaultStuckThreshold = 5

// Config configures automatic conversation compaction.
type Config struct {
	// Enabled controls whether automatic compaction runs. Default: true.
	Enabled bool

	// ContextWindow is the model's context window in tokens.
	ContextWindow int

	// ReserveTokens is the budget reserved for the model response.
	ReserveTokens int

	// KeepRecentTokens is how many tokens of recent messages to keep verbatim.
	KeepRecentTokens int

	// MaxToolResultChars is the max chars per tool result in summarization input.
	MaxToolResultChars int

	// EffectivePercent is the percentage of ContextWindow to actually use (0-100).
	EffectivePercent int

	// SummarizationModel overrides the model used for summarization.
	SummarizationModel string

	// SummarizationProvider overrides the provider for summarization.
	SummarizationProvider agent.Provider

	// SummarizationFocus is optional text appended to the summarization prompt.
	SummarizationFocus string

	// UserMessageTailTokens is the token budget for re-including recent real
	// user messages after compaction alongside the summary. This gives the model
	// actual request context rather than only the summary.
	// Default: 20000. Zero means disabled.
	UserMessageTailTokens int

	// StuckThreshold is the number of consecutive compaction attempts (where
	// ShouldCompact returns true) that fail to produce a compacted history
	// before the compactor returns agent.ErrCompactionStuck. Zero uses
	// DefaultStuckThreshold.
	StuckThreshold int
}

// DefaultConfig returns a Config with sensible defaults.
func DefaultConfig() Config {
	return Config{
		Enabled:               true,
		ContextWindow:         DefaultContextWindow,
		ReserveTokens:         DefaultReserveTokens,
		KeepRecentTokens:      DefaultKeepRecentTokens,
		MaxToolResultChars:    DefaultMaxToolResultChars,
		EffectivePercent:      DefaultEffectivePercent,
		UserMessageTailTokens: DefaultUserMessageTailTokens,
	}
}

// FindCutPoint walks backwards from the end of messages, accumulating token
// estimates, and returns the index of the first message to keep. Messages
// before this index will be summarized. The cut is always at a valid turn
// boundary — never between a tool call and its result.
func FindCutPoint(messages []agent.Message, keepRecentTokens int) int {
	if len(messages) == 0 {
		return 0
	}
	if keepRecentTokens <= 0 {
		return len(messages)
	}

	accumulated := 0
	cutIndex := 0

	for i := len(messages) - 1; i >= 0; i-- {
		tokens := EstimateMessageTokens(messages[i])
		accumulated += tokens

		if accumulated >= keepRecentTokens {
			// Find a valid cut point at or after this index
			cutIndex = findValidBoundary(messages, i)
			break
		}
	}

	return cutIndex
}

// findValidBoundary scans forward from index to find a valid turn boundary.

