			"openrouter": {Type: "openrouter", BaseURL: openrouter.URL + "/api/v1"},
			"studio":     {Type: "lmstudio", BaseURL: lmstudio.URL + "/v1"},
			"vidar-omlx": {Type: "omlx", BaseURL: omlx.URL + "/v1"},
